CREATE OR REPLACE FUNCTION public._trigger_notification_multi(p_type text, p_recipient_ids uuid[], p_recipient_type text, p_sender_id uuid, p_sender_name text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'net'
AS $function$
DECLARE
  v_secret TEXT;
BEGIN
  IF p_recipient_ids IS NULL OR array_length(p_recipient_ids, 1) = 0 THEN
    RETURN;
  END IF;

  v_secret := current_setting('app.notification_secret', true);
  IF v_secret IS NULL OR v_secret = '' THEN RETURN; END IF;

  PERFORM net.http_post(
    url     := 'https://biilrksornvoqtalftty.supabase.co/functions/v1/send-notification',
    headers := jsonb_build_object(
      'Content-Type',          'application/json',
      'x-notification-secret', v_secret
    ),
    body := jsonb_build_object(
      'type',            p_type,
      'recipient_ids',   to_jsonb(p_recipient_ids),
      'recipient_type',  p_recipient_type,
      'sender_id',       p_sender_id,
      'sender_name',     p_sender_name,
      'data',            p_data
    )
  );
EXCEPTION WHEN OTHERS THEN
  NULL;
END; $function$

CREATE OR REPLACE FUNCTION public._update_weekly_streak(p_child_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_current_week date := date_trunc('week', now())::date;
  v_last_week    date;
  v_streak       int;
  v_new_streak   int;
BEGIN
  SELECT last_active_week, streak INTO v_last_week, v_streak
  FROM children WHERE id = p_child_id;

  IF v_last_week = v_current_week THEN
    -- Same ISO week: activity already counted this week, no change
    RETURN COALESCE(v_streak, 0);
  ELSIF v_last_week = (v_current_week - interval '7 days')::date THEN
    -- Exactly one ISO week behind: consecutive week, increment
    v_new_streak := COALESCE(v_streak, 0) + 1;
    UPDATE children
      SET streak = v_new_streak,
          last_active_week = v_current_week
      WHERE id = p_child_id;
    RETURN v_new_streak;
  ELSE
    -- Gap detected (missed ≥1 week) or first ever activity: start fresh
    UPDATE children
      SET streak = 1,
          last_active_week = v_current_week,
          streak_started_at = now()
      WHERE id = p_child_id;
    RETURN 1;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.accept_circle_request(p_request_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_from_id    uuid;
  v_to_id      uuid;
  v_from_token text;
  v_to_name    text;
BEGIN
  UPDATE circle_requests
  SET status = 'accepted'
  WHERE id = p_request_id
  RETURNING from_id, to_id INTO v_from_id, v_to_id;

  IF v_from_id IS NULL THEN
    RAISE EXCEPTION 'request_not_found';
  END IF;

  INSERT INTO circles(child_id, friend_id, status)
  VALUES (v_from_id, v_to_id, 'active')
  ON CONFLICT (child_id, friend_id) DO UPDATE
    SET status = 'active', removed_at = NULL, removed_by = NULL;

  INSERT INTO circles(child_id, friend_id, status)
  VALUES (v_to_id, v_from_id, 'active')
  ON CONFLICT (child_id, friend_id) DO UPDATE
    SET status = 'active', removed_at = NULL, removed_by = NULL;

  SELECT push_token   INTO v_from_token FROM children WHERE id = v_from_id;
  SELECT display_name INTO v_to_name    FROM children WHERE id = v_to_id;

  PERFORM _trigger_notification(
    'friend_accepted', v_from_id, 'child', v_to_id, v_to_name, '{}'::jsonb
  );

  RETURN json_build_object(
    'from_id',         v_from_id,
    'to_id',           v_to_id,
    'from_push_token', v_from_token
  );
END; $function$

CREATE OR REPLACE FUNCTION public.biometric_login_child(p_child_id uuid, p_device_id text, p_biometric_token text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_child     children%ROWTYPE;
  v_parent    parents%ROWTYPE;
  v_raw_token text;
  v_hash      text;
  v_expires   timestamptz := now() + interval '1 hour';
  v_abs_exp   timestamptz := now() + interval '30 days';
  v_allowed   boolean;
BEGIN
  IF p_biometric_token IS NULL OR length(p_biometric_token) <> 64 THEN
    RETURN NULL;
  END IF;
  IF p_device_id IS NULL OR p_device_id = '' THEN
    RETURN NULL;
  END IF;

  -- ── Device throttle ────────────────────────────────────────────────────────
  v_allowed := _rl_attempt(
    'rl_bio_login', p_device_id,
    20, interval '60 minutes', interval '30 minutes'
  );
  IF NOT v_allowed THEN
    RAISE EXCEPTION 'rate_limit_exceeded';
  END IF;

  -- ── Credential check ───────────────────────────────────────────────────────
  SELECT * INTO v_child
    FROM children
    WHERE id                   = p_child_id
      AND biometric_enabled    = true
      AND last_device_id       = p_device_id
      AND biometric_token_hash = encode(digest(p_biometric_token, 'sha256'), 'hex');

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- ── Success ────────────────────────────────────────────────────────────────
  PERFORM _rl_clear('rl_bio_login', p_device_id);

  UPDATE children SET last_biometric_login = now() WHERE id = p_child_id;
  SELECT * INTO v_parent FROM parents WHERE id = v_child.parent_id;

  v_raw_token := encode(gen_random_bytes(32), 'hex');
  v_hash      := encode(digest(v_raw_token, 'sha256'), 'hex');
  PERFORM revoke_all_child_sessions(v_child.id, 'superseded_by_new_login');
  INSERT INTO child_sessions (child_id, token_hash, device_id, expires_at, absolute_expires_at)
    VALUES (v_child.id, v_hash, p_device_id, v_expires, v_abs_exp);

  RETURN json_build_object(
    'child', json_build_object(
      'id',                v_child.id,
      'display_name',      v_child.display_name,
      'username',          v_child.username,
      'avatar_emoji',      v_child.avatar_emoji,
      'profile_image_url', v_child.profile_image_url,
      'trust_score',       v_child.trust_score,
      'wallet_balance',    v_child.wallet_balance,
      'loaned_out',        v_child.loaned_out,
      'borrowed',          v_child.borrowed,
      'streak',            v_child.streak,
      'repaid',            v_child.repaid,
      'missed',            v_child.missed,
      'total_borrowed',    v_child.total_borrowed,
      'total_lent',        v_child.total_lent,
      'times_borrowed',    v_child.times_borrowed,
      'times_lent',        v_child.times_lent,
      'points',            v_child.points,
      'age',               v_child.age,
      'mobile',            v_child.mobile,
      'biometric_enabled', v_child.biometric_enabled,
      'last_device_id',    v_child.last_device_id,
      'account_frozen',    v_child.account_frozen,
      'parent_debt',       v_child.parent_debt
    ),
    'parent', json_build_object(
      'id',                     v_parent.id,
      'first_name',             v_parent.first_name,
      'last_name',              v_parent.last_name,
      'display_name',           v_parent.display_name,
      'safety_pool_limit',      v_parent.safety_pool_limit,
      'safety_pool_used',       v_parent.safety_pool_used,
      'safety_pool_reserved',   v_parent.safety_pool_reserved,
      'weekly_allowance',       v_parent.weekly_allowance,
      'allowance_frequency',    v_parent.allowance_frequency,
      'allowance_active',       v_parent.allowance_active,
      'allowance_next_payment', v_parent.allowance_next_payment,
      'passcode_created',       v_parent.passcode_created,
      'marketing_notifications',v_parent.marketing_notifications,
      'profile_image_url',      v_parent.profile_image_url
    ),
    'session_token',      v_raw_token,
    'session_expires_at', v_expires
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.confirm_parent_repayment(p_child_id uuid, p_parent_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_debt          numeric;
  v_child_balance numeric;
BEGIN
  -- Lock child row and read both debt and current balance atomically.
  SELECT COALESCE(parent_debt, 0), wallet_balance
  INTO   v_debt, v_child_balance
  FROM   children
  WHERE  id = p_child_id AND parent_id = p_parent_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN json_build_object('error', 'not_parent');
  END IF;

  -- Short-circuit: nothing to repay
  IF v_debt = 0 THEN
    RETURN json_build_object('repaid', 0);
  END IF;

  -- Balance check before any write
  IF COALESCE(v_child_balance, 0) < v_debt THEN
    RAISE EXCEPTION 'Insufficient balance: child has £% but owes £%',
      to_char(COALESCE(v_child_balance, 0), 'FM999990.00'),
      to_char(v_debt, 'FM999990.00');
  END IF;

  -- Exact deduction (balance check above guarantees this stays >= 0)
  UPDATE children SET
    wallet_balance = wallet_balance - v_debt,
    parent_debt    = 0,
    account_frozen = false
  WHERE id = p_child_id;

  UPDATE parents
  SET safety_pool_used = GREATEST(0, COALESCE(safety_pool_used, 0) - v_debt)
  WHERE id = p_parent_id;

  RETURN json_build_object('repaid', v_debt);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_money_request(p_from_id uuid, p_amount numeric, p_deadline_days integer, p_session_token text, p_device_id text, p_reason text DEFAULT ''::text, p_reason_emoji text DEFAULT '💸'::text, p_viewer_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_req_id     uuid;
  v_trust      int;
  v_max_borrow numeric;
  v_frozen     boolean;
  v_from_name  text;
  v_viewer_ids uuid[];
BEGIN
  -- Amount validation first — before session check or any DB read
  PERFORM public.require_valid_gbp_amount(p_amount, 'request amount');

  PERFORM require_valid_child_session(p_from_id, p_session_token, p_device_id);

  SELECT trust_score, COALESCE(account_frozen, false)
    INTO v_trust, v_frozen
    FROM children WHERE id = p_from_id;

  IF v_frozen THEN RAISE EXCEPTION 'account_frozen'; END IF;

  IF EXISTS (
    SELECT 1 FROM money_requests
    WHERE from_id = p_from_id AND status IN ('pending', 'funded')
  ) THEN
    RAISE EXCEPTION 'already_borrowing';
  END IF;

  v_max_borrow := CASE
    WHEN v_trust < 50 THEN 20
    WHEN v_trust < 70 THEN 30
    WHEN v_trust < 85 THEN 50
    ELSE 100
  END;

  IF p_amount > v_max_borrow THEN
    RAISE EXCEPTION 'amount_exceeds_limit:%', v_max_borrow;
  END IF;

  INSERT INTO money_requests
    (from_id, amount, reason, reason_emoji, deadline_days, repay_by_date, expires_at, viewer_ids)
  VALUES (
    p_from_id, p_amount, p_reason, p_reason_emoji, p_deadline_days,
    (now() + (p_deadline_days || ' days'::text)::interval)::date,
    now() + interval '24 hours',
    p_viewer_ids
  ) RETURNING id INTO v_req_id;

  PERFORM _update_weekly_streak(p_from_id);

  SELECT array_agg(ci.friend_id) INTO v_viewer_ids
    FROM circles ci
    WHERE ci.child_id = p_from_id
      AND ci.status   = 'active'
      AND (p_viewer_ids IS NULL OR ci.friend_id = ANY(p_viewer_ids));

  SELECT display_name INTO v_from_name FROM children WHERE id = p_from_id;

  PERFORM _trigger_notification_multi(
    'money_request', v_viewer_ids, 'child', p_from_id, v_from_name,
    jsonb_build_object('amount', p_amount, 'request_id', v_req_id)
  );

  RETURN json_build_object('request_id', v_req_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.decline_circle_request(p_request_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_from_token text;
  v_from_id    uuid;
  v_to_id      uuid;
  v_to_name    text;
BEGIN
  UPDATE circle_requests SET status = 'declined'
  WHERE id = p_request_id
  RETURNING from_id, to_id INTO v_from_id, v_to_id;

  SELECT push_token   INTO v_from_token FROM children WHERE id = v_from_id;
  SELECT display_name INTO v_to_name    FROM children WHERE id = v_to_id;

  PERFORM _trigger_notification(
    'friend_declined', v_from_id, 'child', v_to_id, v_to_name, '{}'::jsonb
  );

  RETURN json_build_object('from_push_token', v_from_token);
END; $function$

CREATE OR REPLACE FUNCTION public.enable_biometric(p_child_id uuid, p_device_id text, p_biometric_token_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF p_biometric_token_hash IS NULL OR length(p_biometric_token_hash) <> 64 THEN
    RAISE EXCEPTION 'invalid_biometric_token_hash';
  END IF;
  IF p_device_id IS NULL OR p_device_id = '' THEN
    RAISE EXCEPTION 'invalid_device_id';
  END IF;

  UPDATE children
    SET biometric_enabled     = true,
        last_device_id        = p_device_id,
        biometric_token_hash  = p_biometric_token_hash
    WHERE id = p_child_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.fund_money_request(p_request_id uuid, p_funder_id uuid, p_amount numeric, p_session_token text, p_device_id text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_borrower_id    uuid;
  v_request_amount numeric;
  v_parent_id      uuid;
  v_funder_user    text;
  v_funder_name    text;
  v_borrower_name  text;
  v_borrower_user  text;
  v_amt_str        text;
  v_frozen         boolean;
  v_pool_avail     numeric;
  v_funder_balance numeric;
BEGIN
  -- Amount validation first — before session check or any DB read
  PERFORM public.require_valid_gbp_amount(p_amount, 'funding amount');

  PERFORM require_valid_child_session(p_funder_id, p_session_token, p_device_id);

  -- Read the pending request (no lock — just confirming it exists and is pending)
  SELECT from_id, amount INTO v_borrower_id, v_request_amount
    FROM money_requests
    WHERE id = p_request_id AND status = 'pending';
  IF v_borrower_id IS NULL THEN
    RAISE EXCEPTION 'Request not found or already funded';
  END IF;

  -- Validate the client-supplied amount matches the stored request amount
  IF p_amount <> v_request_amount THEN
    RAISE EXCEPTION 'Amount mismatch: request is for %, client sent %',
      v_request_amount, p_amount;
  END IF;

  SELECT COALESCE(account_frozen, false) INTO v_frozen
    FROM children WHERE id = v_borrower_id;
  IF v_frozen THEN RAISE EXCEPTION 'borrower_frozen'; END IF;

  -- Lock the borrower's parent FOR UPDATE FIRST (consistent lock ordering).
  -- This makes the availability check + reservation increment atomic.
  SELECT p.id,
         (COALESCE(p.safety_pool_limit,    0)
          - COALESCE(p.safety_pool_used,   0)
          - COALESCE(p.safety_pool_reserved, 0))
    INTO v_parent_id, v_pool_avail
    FROM parents p
    JOIN children c ON c.parent_id = p.id
    WHERE c.id = v_borrower_id
    FOR UPDATE;

  IF v_parent_id IS NULL THEN
    RAISE EXCEPTION 'Parent not found for borrower';
  END IF;

  IF COALESCE(v_pool_avail, 0) < p_amount THEN
    RAISE EXCEPTION 'safety_pool_insufficient';
  END IF;

  -- Lock funder child AFTER parent (consistent ordering: parent before child)
  SELECT wallet_balance INTO v_funder_balance
    FROM children WHERE id = p_funder_id FOR UPDATE;
  IF COALESCE(v_funder_balance, 0) < p_amount THEN
    RAISE EXCEPTION 'Insufficient balance to fund this request';
  END IF;

  -- Fund the request and record the reservation amount atomically
  UPDATE money_requests
    SET status                      = 'funded',
        funded_by                   = p_funder_id,
        funded_at                   = now(),
        safety_pool_reserved_amount = p_amount
    WHERE id = p_request_id AND status = 'pending'
    RETURNING from_id INTO v_borrower_id;

  IF v_borrower_id IS NULL THEN
    RAISE EXCEPTION 'Request not found or already funded';
  END IF;

  -- Reserve coverage in the parent (parent row still locked from above)
  UPDATE parents
    SET safety_pool_reserved = COALESCE(safety_pool_reserved, 0) + p_amount
    WHERE id = v_parent_id;

  SELECT username,     display_name INTO v_funder_user,   v_funder_name   FROM children WHERE id = p_funder_id;
  SELECT display_name, username     INTO v_borrower_name, v_borrower_user FROM children WHERE id = v_borrower_id;

  v_amt_str := '£' || to_char(p_amount, 'FM999990.00');

  UPDATE children SET
    wallet_balance = wallet_balance - p_amount,
    loaned_out     = loaned_out     + p_amount,
    total_lent     = total_lent     + p_amount,
    times_lent     = times_lent     + 1,
    trust_score    = LEAST(100, trust_score + 2),
    points         = points         + 2
  WHERE id = p_funder_id;

  PERFORM _update_weekly_streak(p_funder_id);

  UPDATE children SET
    wallet_balance = wallet_balance + p_amount,
    borrowed       = borrowed       + p_amount,
    total_borrowed = total_borrowed + p_amount,
    times_borrowed = times_borrowed + 1
  WHERE id = v_borrower_id;

  INSERT INTO transactions (child_id, type, amount, description, counterparty) VALUES
    (p_funder_id,   'lend',   -p_amount,
     v_amt_str || ' lent to @'       || v_borrower_user, v_borrower_name),
    (v_borrower_id, 'borrow',  p_amount,
     v_amt_str || ' borrowed from @' || v_funder_user,   NULL);

  PERFORM _trigger_notification(
    'money_funded', v_borrower_id, 'child', p_funder_id, v_funder_name,
    jsonb_build_object('amount', p_amount, 'request_id', p_request_id)
  );

  RETURN json_build_object('borrower_id', v_borrower_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_child_transactions(p_child_id uuid, p_limit integer DEFAULT 20)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_result json;
BEGIN
  SELECT json_agg(row_to_json(r)) INTO v_result
  FROM (
    SELECT id, type, amount, description, counterparty, created_at
    FROM transactions WHERE child_id = p_child_id
    ORDER BY created_at DESC LIMIT p_limit
  ) r;
  RETURN COALESCE(v_result, '[]'::json);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_outgoing_pending_requests(p_child_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_results json;
BEGIN
  SELECT json_agg(row_to_json(r)) INTO v_results
  FROM (
    SELECT cr.to_id AS id
    FROM circle_requests cr
    WHERE cr.from_id = p_child_id AND cr.status = 'pending'
  ) r;
  RETURN COALESCE(v_results, '[]'::json);
END;
$function$

CREATE OR REPLACE FUNCTION public.login_child(p_username text, p_password text, p_device_id text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_child     children%ROWTYPE;
  v_parent    parents%ROWTYPE;
  v_raw_token text;
  v_hash      text;
  v_expires   timestamptz := now() + interval '1 hour';
  v_abs_exp   timestamptz := now() + interval '30 days';
  v_allowed   boolean;
  c_dummy CONSTANT text :=
    '$2a$10$N9qo8uLOickgx2ZMRZoMyeIjZAgcfl7p92ldGxad68LJZdL17lhWy';
BEGIN
  IF p_device_id IS NULL OR p_device_id = '' THEN
    RAISE EXCEPTION 'device_id_required';
  END IF;

  -- ── Device throttle ────────────────────────────────────────────────────────
  -- Recorded before we even look up the username so enumeration attempts
  -- consume the device budget the same as wrong-password attempts.
  v_allowed := _rl_attempt(
    'rl_child_login_dev', p_device_id,
    20, interval '30 minutes', interval '10 minutes'
  );
  IF NOT v_allowed THEN
    RAISE EXCEPTION 'rate_limit_exceeded';
  END IF;

  -- ── Username lookup ────────────────────────────────────────────────────────
  SELECT * INTO v_child
    FROM children
    WHERE username = lower(p_username) AND password_hash IS NOT NULL;

  IF NOT FOUND THEN
    -- Timing equalization: unknown username costs the same bcrypt time as wrong password.
    -- Device throttle already incremented above; no per-username row created here.
    PERFORM crypt(p_password, c_dummy);
    RETURN NULL;
  END IF;

  -- ── Account throttle ───────────────────────────────────────────────────────
  -- Only reached for known usernames, preventing junk rows for nonexistent accounts.
  v_allowed := _rl_attempt(
    'rl_child_login_acc', lower(p_username),
    10, interval '15 minutes', interval '5 minutes'
  );
  IF NOT v_allowed THEN
    RAISE EXCEPTION 'rate_limit_exceeded';
  END IF;

  -- ── Credential check ───────────────────────────────────────────────────────
  IF crypt(p_password, v_child.password_hash) <> v_child.password_hash THEN
    -- Both counters were incremented above; leave them incremented.
    RETURN NULL;
  END IF;

  -- ── Success: clear rate-limit counters ────────────────────────────────────
  PERFORM _rl_clear('rl_child_login_dev', p_device_id);
  PERFORM _rl_clear('rl_child_login_acc', lower(p_username));

  -- ── Issue session token ───────────────────────────────────────────────────
  SELECT * INTO v_parent FROM parents WHERE id = v_child.parent_id;
  v_raw_token := encode(gen_random_bytes(32), 'hex');
  v_hash      := encode(digest(v_raw_token, 'sha256'), 'hex');
  PERFORM revoke_all_child_sessions(v_child.id, 'superseded_by_new_login');
  INSERT INTO child_sessions (child_id, token_hash, device_id, expires_at, absolute_expires_at)
    VALUES (v_child.id, v_hash, p_device_id, v_expires, v_abs_exp);

  RETURN json_build_object(
    'child', json_build_object(
      'id',                v_child.id,
      'display_name',      v_child.display_name,
      'username',          v_child.username,
      'avatar_emoji',      v_child.avatar_emoji,
      'profile_image_url', v_child.profile_image_url,
      'trust_score',       v_child.trust_score,
      'wallet_balance',    v_child.wallet_balance,
      'loaned_out',        v_child.loaned_out,
      'borrowed',          v_child.borrowed,
      'streak',            v_child.streak,
      'repaid',            v_child.repaid,
      'missed',            v_child.missed,
      'total_borrowed',    v_child.total_borrowed,
      'total_lent',        v_child.total_lent,
      'times_borrowed',    v_child.times_borrowed,
      'times_lent',        v_child.times_lent,
      'points',            v_child.points,
      'age',               v_child.age,
      'mobile',            v_child.mobile,
      'biometric_enabled', v_child.biometric_enabled,
      'last_device_id',    v_child.last_device_id,
      'account_frozen',    v_child.account_frozen,
      'parent_debt',       v_child.parent_debt
    ),
    'parent', json_build_object(
      'id',                     v_parent.id,
      'first_name',             v_parent.first_name,
      'last_name',              v_parent.last_name,
      'display_name',           v_parent.display_name,
      'safety_pool_limit',      v_parent.safety_pool_limit,
      'safety_pool_used',       v_parent.safety_pool_used,
      'safety_pool_reserved',   v_parent.safety_pool_reserved,
      'weekly_allowance',       v_parent.weekly_allowance,
      'allowance_frequency',    v_parent.allowance_frequency,
      'allowance_active',       v_parent.allowance_active,
      'allowance_next_payment', v_parent.allowance_next_payment,
      'passcode_created',       v_parent.passcode_created,
      'marketing_notifications',v_parent.marketing_notifications,
      'profile_image_url',      v_parent.profile_image_url
    ),
    'session_token',      v_raw_token,
    'session_expires_at', v_expires
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.parent_send_to_child(p_user_id uuid, p_child_id uuid, p_amount numeric, p_parent_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tx_id      text := 'ps_' || floor(extract(epoch from now()))::bigint;
  v_amount_str text;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_user_id THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;
  PERFORM public.require_valid_gbp_amount(p_amount, 'transfer amount');

  IF NOT EXISTS (
    SELECT 1 FROM children WHERE id = p_child_id AND parent_id = p_user_id
  ) THEN
    RAISE EXCEPTION 'not_parent';
  END IF;

  v_amount_str := CASE
    WHEN p_amount = floor(p_amount) THEN floor(p_amount)::integer::text
    ELSE round(p_amount, 2)::text
  END;

  UPDATE children SET wallet_balance = wallet_balance + p_amount WHERE id = p_child_id;

  INSERT INTO transactions (child_id, type, amount, description, counterparty)
    VALUES (p_child_id, 'parent_transfer', p_amount,
            p_parent_name || ' sent you £' || v_amount_str, p_parent_name);

  INSERT INTO activity_feed (child_id, id, emoji, text, type)
    VALUES (p_child_id, 'act_' || v_tx_id, '💚',
            p_parent_name || ' sent you £' || v_amount_str, 'topup');
END;
$function$

CREATE OR REPLACE FUNCTION public.repay_money_request(p_request_id uuid, p_borrower_id uuid, p_session_token text, p_device_id text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_parent_id        uuid;
  v_funder_id        uuid;
  v_amount           numeric;
  v_reserved_amount  numeric;
  v_borrower_user    text;
  v_borrower_name    text;
  v_funder_name      text;
  v_funder_user      text;
  v_amt_str          text;
  v_act_id           text;
  v_borrower_balance numeric;
BEGIN
  -- Session validation is the first operation — before any read or write
  PERFORM require_valid_child_session(p_borrower_id, p_session_token, p_device_id);

  -- Get parent_id without locking (needed to establish lock ordering)
  SELECT parent_id INTO v_parent_id
    FROM children WHERE id = p_borrower_id;
  IF v_parent_id IS NULL THEN
    RAISE EXCEPTION 'Borrower not found';
  END IF;

  -- Lock parent FIRST (consistent ordering: parent before child before money_requests).
  -- This prevents deadlocks with fund_money_request and process_due_loan_defaults,
  -- both of which also acquire the parent lock before other row locks.
  PERFORM 1 FROM parents WHERE id = v_parent_id FOR UPDATE;

  -- Lock borrower child AFTER parent
  SELECT wallet_balance INTO v_borrower_balance
    FROM children WHERE id = p_borrower_id FOR UPDATE;

  -- Lock money_requests AFTER child
  SELECT funded_by, amount, safety_pool_reserved_amount
    INTO v_funder_id, v_amount, v_reserved_amount
    FROM money_requests
    WHERE id      = p_request_id
      AND from_id = p_borrower_id
      AND status  = 'funded'
    FOR UPDATE;

  IF v_funder_id IS NULL THEN
    RAISE EXCEPTION 'Request not found or not in funded state';
  END IF;

  IF COALESCE(v_borrower_balance, 0) < v_amount THEN
    RAISE EXCEPTION 'Insufficient balance to repay this loan';
  END IF;

  SELECT username,     display_name INTO v_borrower_user, v_borrower_name FROM children WHERE id = p_borrower_id;
  SELECT display_name, username     INTO v_funder_name,   v_funder_user   FROM children WHERE id = v_funder_id;

  v_amt_str := '£' || to_char(v_amount, 'FM999990.00');
  v_act_id  := 'recv_' || p_request_id::text;

  -- Mark as repaid and stamp reservation release time
  UPDATE money_requests
    SET status                            = 'repaid',
        repaid_at                         = now(),
        safety_pool_reservation_released_at = now()
    WHERE id = p_request_id;

  UPDATE children SET
    wallet_balance = wallet_balance - v_amount,
    borrowed       = GREATEST(0, borrowed - v_amount),
    repaid         = repaid         + 1,
    trust_score    = LEAST(100, trust_score + 5),
    points         = points         + 5
  WHERE id = p_borrower_id;

  PERFORM _update_weekly_streak(p_borrower_id);

  UPDATE children SET
    wallet_balance = wallet_balance + v_amount,
    loaned_out     = GREATEST(0, loaned_out - v_amount)
  WHERE id = v_funder_id;

  -- Release Safety Pool reservation (parent row still locked from above)
  IF v_reserved_amount IS NOT NULL AND v_reserved_amount > 0 THEN
    UPDATE parents
      SET safety_pool_reserved = GREATEST(0, COALESCE(safety_pool_reserved, 0) - v_reserved_amount)
      WHERE id = v_parent_id;
  END IF;

  INSERT INTO transactions (child_id, type, amount, description, counterparty) VALUES
    (p_borrower_id, 'repay',   -v_amount,
     'Repaid '   || v_amt_str || ' to @'   || v_funder_user,   v_funder_name),
    (v_funder_id,   'receive',  v_amount,
     'Received ' || v_amt_str || ' from @' || v_borrower_user, NULL);

  INSERT INTO activity_feed (child_id, id, emoji, text, type)
    VALUES (v_funder_id, v_act_id, '✅',
            '@' || v_borrower_user || ' repaid you ' || v_amt_str, 'repaid')
    ON CONFLICT (id) DO NOTHING;

  PERFORM _trigger_notification(
    'money_repaid', v_funder_id, 'child', p_borrower_id, v_borrower_name,
    jsonb_build_object('amount', v_amount, 'request_id', p_request_id)
  );

  RETURN json_build_object('funder_id', v_funder_id, 'amount', v_amount);
END;
$function$

CREATE OR REPLACE FUNCTION public.require_valid_child_session(p_child_id uuid, p_session_token text, p_device_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_session child_sessions%ROWTYPE;
  v_hash    text;
  v_now     timestamptz := now();
BEGIN
  IF p_session_token IS NULL OR length(p_session_token) <> 64 THEN
    RAISE EXCEPTION 'invalid_child_session';
  END IF;
  IF p_device_id IS NULL OR p_device_id = '' THEN
    RAISE EXCEPTION 'invalid_child_session';
  END IF;
  IF p_child_id IS NULL THEN
    RAISE EXCEPTION 'invalid_child_session';
  END IF;

  v_hash := encode(digest(p_session_token, 'sha256'), 'hex');

  SELECT * INTO v_session
    FROM child_sessions
    WHERE token_hash = v_hash
      AND child_id   = p_child_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invalid_child_session';
  END IF;

  IF v_session.device_id <> p_device_id THEN
    RAISE EXCEPTION 'invalid_child_session';
  END IF;

  IF v_session.revoked_at IS NOT NULL THEN
    RAISE EXCEPTION 'child_session_revoked';
  END IF;

  IF v_session.expires_at < v_now THEN
    RAISE EXCEPTION 'child_session_expired';
  END IF;

  IF v_session.absolute_expires_at < v_now THEN
    RAISE EXCEPTION 'child_session_expired';
  END IF;

  IF EXISTS (SELECT 1 FROM children WHERE id = p_child_id AND account_frozen = true) THEN
    RAISE EXCEPTION 'invalid_child_session';
  END IF;

  UPDATE child_sessions
    SET last_seen_at = v_now,
        expires_at   = LEAST(v_now + interval '1 hour', v_session.absolute_expires_at)
    WHERE id = v_session.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.revoke_child_session(p_session_token text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_hash text;
BEGIN
  -- Silently ignore malformed or missing tokens — never log the raw token
  IF p_session_token IS NULL OR length(p_session_token) <> 64 THEN
    RETURN;
  END IF;
  v_hash := encode(digest(p_session_token, 'sha256'), 'hex');
  UPDATE child_sessions
    SET revoked_at     = now(),
        revoked_reason = 'logout'
    WHERE token_hash = v_hash
      AND revoked_at IS NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.send_circle_request(p_from_id uuid, p_to_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_to_token  text;
  v_from_name text;
BEGIN
  IF p_from_id = p_to_id THEN
    RAISE EXCEPTION 'cannot_add_self';
  END IF;

  IF EXISTS (
    SELECT 1 FROM circles
    WHERE status = 'active'
      AND ((child_id = p_from_id AND friend_id = p_to_id)
        OR (child_id = p_to_id   AND friend_id = p_from_id))
  ) THEN
    RAISE EXCEPTION 'already_friends';
  END IF;

  IF EXISTS (
    SELECT 1 FROM circle_requests
    WHERE status = 'pending'
      AND ((from_id = p_from_id AND to_id = p_to_id)
        OR (from_id = p_to_id   AND to_id = p_from_id))
  ) THEN
    RAISE EXCEPTION 'already_pending';
  END IF;

  DELETE FROM circle_requests WHERE from_id = p_from_id AND to_id = p_to_id;

  INSERT INTO circle_requests(from_id, to_id, status, created_at)
  VALUES (p_from_id, p_to_id, 'pending', now());

  SELECT push_token    INTO v_to_token  FROM children WHERE id = p_to_id;
  SELECT display_name  INTO v_from_name FROM children WHERE id = p_from_id;

  PERFORM _trigger_notification(
    'friend_request', p_to_id, 'child', p_from_id, v_from_name, '{}'::jsonb
  );

  RETURN json_build_object('push_token', v_to_token);
END; $function$

CREATE OR REPLACE FUNCTION public.set_parent_passcode(p_parent_id uuid, p_pin text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_allowed boolean;
BEGIN
  -- 1. Caller-identity guard — fails immediately for absent or mismatched JWT.
  IF auth.uid() IS NULL OR auth.uid() <> p_parent_id THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  -- 2. Format validation — must be exactly 6 decimal digits.
  IF p_pin !~ '^[0-9]{6}$' THEN
    RAISE EXCEPTION 'invalid_pin_format';
  END IF;

  -- 3. Weak-PIN rejection.
  IF p_pin = ANY(ARRAY[
    '000000','111111','222222','333333','444444',
    '555555','666666','777777','888888','999999',
    '123456','654321','012345','543210'
  ]) THEN
    RAISE EXCEPTION 'weak_pin';
  END IF;

  -- 4. Rate guard before expensive bcrypt work.
  --    Threat: authenticated abuse and resource exhaustion — bcrypt at cost=10 takes
  --    ~100 ms; an unconstrained loop could consume significant DB CPU.
  v_allowed := _rl_attempt(
    'rl_set_passcode', p_parent_id::text,
    10, interval '10 minutes', interval '30 minutes'
  );
  IF NOT v_allowed THEN
    RAISE EXCEPTION 'rate_limit_exceeded';
  END IF;

  -- 5. Signal the column-protection trigger that this UPDATE is trusted.
  --    The flag is transaction-local (third arg = true) so it cannot persist
  --    beyond this request's transaction or be set by an external API caller.
  PERFORM set_config('truzo.allow_passcode_write', 'true', true);

  -- 6. bcrypt — expensive work only after all cheap guards pass.
  UPDATE public.parents
  SET
    passcode_hash       = crypt(p_pin, gen_salt('bf', 10)),
    passcode_created    = true,
    passcode_created_at = now()
  WHERE id = p_parent_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.top_up_safety_pool(p_parent_id uuid, p_amount numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_new_limit numeric;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_parent_id THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;
  PERFORM public.require_valid_gbp_amount(p_amount, 'top-up amount');
  UPDATE parents
    SET safety_pool_limit = COALESCE(safety_pool_limit, 0) + p_amount
  WHERE id = p_parent_id
  RETURNING safety_pool_limit INTO v_new_limit;
  RETURN v_new_limit;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_safety_pool(p_parent_id uuid, p_new_limit numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_used     numeric;
  v_reserved numeric;
  v_combined numeric;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_parent_id THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;
  IF p_new_limit IS NULL THEN
    RAISE EXCEPTION 'invalid_amount: limit must not be null';
  END IF;
  IF p_new_limit < 0 THEN
    RAISE EXCEPTION 'invalid_amount: limit cannot be negative';
  END IF;
  IF p_new_limit <> round(p_new_limit, 2) THEN
    RAISE EXCEPTION 'amount_precision_invalid: limit must have at most 2 decimal places';
  END IF;

  SELECT COALESCE(safety_pool_used, 0), COALESCE(safety_pool_reserved, 0)
    INTO v_used, v_reserved
    FROM parents WHERE id = p_parent_id
    FOR UPDATE;

  v_combined := v_used + v_reserved;

  IF p_new_limit < v_combined THEN
    RAISE EXCEPTION
      'Cannot reduce Safety Pool limit to % — used (%) + reserved (%) = % exceeds new limit',
      p_new_limit, v_used, v_reserved, v_combined;
  END IF;

  UPDATE parents
    SET safety_pool_limit        = p_new_limit,
        safety_pool_last_updated = now()
    WHERE id = p_parent_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.verify_parent_passcode(p_parent_id uuid, p_pin text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_stored_hash text;
  v_allowed     boolean;
BEGIN
  -- 1. Rate check BEFORE any hash work.  Counts this attempt regardless of outcome
  --    so null-hash probes cost the same as wrong-PIN attempts.
  v_allowed := _rl_attempt(
    'rl_parent_passcode', p_parent_id::text,
    5, interval '5 minutes', interval '5 minutes'
  );
  IF NOT v_allowed THEN
    RAISE EXCEPTION 'rate_limit_exceeded';
  END IF;

  -- 2. Fetch stored hash (NULL for unknown UUID or passcode not yet configured).
  SELECT passcode_hash INTO v_stored_hash FROM public.parents WHERE id = p_parent_id;

  -- 3. Format guard: reject null, absent-parent, or non-bcrypt values without
  --    calling crypt().  Accepts $2a$, $2b$, $2y$ prefixes; valid bcrypt output
  --    is always exactly 60 characters.  This blocks SHA-256 hashes (64-char hex)
  --    and any other malformed value safely and without a database exception.
  --
  --    All three caller-visible failure modes (unknown UUID, passcode not configured,
  --    wrong PIN) return false — indistinguishable from the caller's perspective.
  IF v_stored_hash IS NULL
     OR v_stored_hash !~ '^\$2[aby]\$[0-9]{2}\$'
     OR length(v_stored_hash) <> 60 THEN
    RETURN false;
  END IF;

  -- 4. bcrypt comparison — only reached when a valid stored hash exists.
  IF crypt(p_pin, v_stored_hash) = v_stored_hash THEN
    PERFORM _rl_clear('rl_parent_passcode', p_parent_id::text);
    RETURN true;
  END IF;

  RETURN false;
END;
$function$
